const fs = require("fs");
const { clickCheckboxViaCDP } = require("../module/clickCheckbox");
const { debugLog, infoLog, errorLog } = require('../module/logger');
const queue = require('../module/queue');

function solveTurnstileMin({ url, proxy, siteKey, action }) {
  const executeRequest = () => {
    return new Promise(async (resolve, reject) => {
      if (!url) return reject("Missing url parameter");
      if (!siteKey) return reject("Missing siteKey parameter");

      const context = await global.browser
        .createBrowserContext({
          proxyServer: proxy ? `http://${proxy.host}:${proxy.port}` : undefined,
        })
        .catch(() => null);
        
      if (!context) return reject("Failed to create browser context");

      let isResolved = false;
      const timeoutMs = global.timeOut || 30000;

      const cl = setTimeout(async () => {
        if (!isResolved) {
          await context.close().catch(() => {});
          reject("Timeout Error");
        }
      }, timeoutMs);

      infoLog(`[app] Request received for ${url} ...`);

      try {
        const page = await context.newPage();

        if (proxy?.username && proxy?.password) {
          await page.authenticate({
            username: proxy.username,
            password: proxy.password,
          });
        }

        await page.setRequestInterception(true);

        page.on("request", async (request) => {
          if ([url, url + "/"].includes(request.url()) && request.resourceType() === "document") {
            let htmlContent = String(fs.readFileSync("./src/data/fakePage.html"));            
            htmlContent = htmlContent.replace(/<site-key>/g, siteKey);            
            
            if (action) {
              htmlContent = htmlContent.replace(/<action>/g, action);
            } else {
              htmlContent = htmlContent.replace(/<action>/g, '');
            }
            
            await request.respond({
              status: 200,
              contentType: "text/html",
              body: htmlContent,
            });
          } else {
            await request.continue();
          }
        });

        await page.goto(url, { waitUntil: "domcontentloaded" });
        

                // ── OPTIMIZED WAITING LOGIC (Race-Condition Free) ───────────────
        infoLog('[solveTurnstileMin] Waiting for token...');
        
        // Reserve half the time for the interactive click solver + post-click wait.
        // This guarantees the main timeout won't close the context while clicking.
        const autoSolveTimeout = Math.max(5000, timeoutMs / 2); 
        
        let token = null;

        await new Promise((r) => setTimeout(r, 1500));

        try {
          // 1. Wait for auto-solve (Managed/Invisible mode)
          const tokenEl = await page.waitForFunction(
            () => {
              const el = document.querySelector('[name="cf-response"]');
              return el && el.value && el.value.length > 10 ? el : false;
            },
            { polling: 100, timeout: autoSolveTimeout }
          );
          token = tokenEl ? await page.evaluate(el => el.value, tokenEl) : null;
        } catch (err) {
          // Expected timeout for interactive challenges. We catch it and move to Phase 2.
          debugLog('[solveTurnstileMin] Auto-solve timed out. Attempting interactive click...');
        }

        // 2. If still no token, trigger the click solver
        if (!token) {
          try {
            // Attempt to click the checkbox (gives it up to 4 seconds to find frame and click)
            await clickCheckboxViaCDP(page, 4000).catch(err => {
              errorLog('[solveTurnstileMin] Click solver error:', err.message);
            });

            // 3. Wait up to 2 seconds after clicking for the token to appear
            const postClickEl = await page.waitForFunction(
              () => {
                const el = document.querySelector('[name="cf-response"]');
                return el && el.value && el.value.length > 10 ? el : false;
              },
              { polling: 100, timeout: 2000 }
            ).catch(() => null);
            
            if (postClickEl) {
              token = await page.evaluate(el => el.value, postClickEl);
            }
          } catch (err) {
            errorLog('[solveTurnstileMin] Unexpected error during click attempt:', err.message);
          }
        }

        isResolved = true;
        clearTimeout(cl);
        await context.close().catch(() => {});
        
        if (!token || token.length < 10) return reject("Failed to get token");
        
        infoLog(`[solveTurnstileMin] ✓ Token solved successfully.`);
        return resolve(token);

      } catch (e) {
        if (!isResolved) {
          await context.close().catch(() => {});
          clearTimeout(cl);
          reject(e.message);
        }
      }
    });
  };
  
  return queue.enqueue(executeRequest, 'solveTurnstileMin');
}

module.exports = solveTurnstileMin;